func handoverConfirmationLabel(item HandoverItem) string {
	return fmt.Sprintf("%d von %d Bestätigungen", item.ConfirmedCount, item.ConfirmationCount)
}
func handoverConfirmationParty(item HandoverConfirmation) string {
	if item.Name != "" {
		return item.Name
	}
	return item.Email
}
func handoverAttachmentKind(item view.AttachmentView) string {
	if item.IsPDF {
		return "PDF"
	}
	return "Datei"
}
func handoverDetailsLabel(item HandoverItem) string {
	parts := make([]string, 0, 4)
	if len(item.Rooms) > 0 {
		word := "Räume"
		if len(item.Rooms) == 1 {
			word = "Raum"
		}
		parts = append(parts, fmt.Sprintf("%d %s", len(item.Rooms), word))
	}
	if len(item.Meters) > 0 {
		parts = append(parts, fmt.Sprintf("%d Zähler", len(item.Meters)))
	}
	if len(item.Keys) > 0 {
		parts = append(parts, fmt.Sprintf("%d Schlüssel", len(item.Keys)))
	}
	if len(item.Attachments) > 0 {
		word := "Dateien"
		if len(item.Attachments) == 1 {
			word = "Datei"
		}
		parts = append(parts, fmt.Sprintf("%d %s", len(item.Attachments), word))
	}
	return strings.Join(parts, " · ")
}

